    assert.match(html, /Math\.max\(STORY_FOLLOW_MIN_DWELL_MS, VIEW_INTERVAL_MS \/ Math\.max\(1, total\)\)/);
    assert.match(html, /function storyStep\(view, index, edgeList, byId\)/);
